"""Package native XCTest PNG attachments for a designer. Requires Pillow; never edits the source PNGs."""
from pathlib import Path
import base64, hashlib, html, io, json, re, shutil, sys
from PIL import Image

out=Path(sys.argv[1]).resolve(); (out/'images').mkdir(parents=True,exist_ok=True)
latest={}
for export in map(Path,sys.argv[2:]):
    for test in json.loads((export/'manifest.json').read_text()):
        for item in test['attachments']:
            source=export/item['exportedFileName']
            name=re.sub(r'_\d+_[A-Fa-f0-9-]+\.png$','',item['suggestedHumanReadableName'])
            if source.suffix=='.png' and re.match(r'^(en|ar|tr|accessibility)-',name):
                latest[name]=(source,item,export.name)

names={'01':'Welcome','02':'Welcome · continued','03':'Storage choice','04':'Cloud consent','05':'Sign in','06':'Email keyboard','07':'Keyboard dismissed','08':'Create account','09':'Starter collections','10':'Starter collections · continued','20':'Home','21':'Manage spaces','22':'Suggested collections','23':'Describe with AI','24':'Manual collection builder','25':'Collection records','26':'New record','27':'Edit record','28':'Record detail','29':'Edit fields','30':'Sensitive-data consent','31':'Insights','32':'Settings','33':'Backup and restore','34':'Sync · account not connected','35':'Devices · local state','36':'Change storage mode','37':'Privacy and recovery','38':'Pro · account required','40':'Import an existing AI reply','41':'Prepared AI prompt','42':'Invalid AI reply','43':'Validated schema preview','44':'Sync · connected test account','45':'Enrolled test device','46':'Delete account confirmation'}
manifest=[];cards=[];seen=set()
for name,(source,item,run) in sorted(latest.items()):
    im=Image.open(source).convert('RGB')
    group=re.sub(r'-(top|bottom|page\d+)$','',name)
    digest=hashlib.sha256(im.tobytes()).hexdigest()
    if (group,digest) in seen: continue
    seen.add((group,digest))
    locale=name.split('-')[0];number=name.split('-')[1]
    title=names.get(number,name.replace('accessibility-','').replace('-',' ').title())
    suffix=name.rsplit('-',1)[-1]
    if suffix in ['bottom','page3','page4']: title+=' · '+('continued' if suffix=='bottom' else suffix.replace('page','page '))
    target=out/'images'/f'{name}.png';shutil.copyfile(source,target)
    preview=io.BytesIO();im.save(preview,'WEBP',quality=85,method=4)
    encoded=base64.b64encode(preview.getvalue()).decode()
    manifest.append({'file':str(target.relative_to(out)),'name':name,'title':title,'language':locale,'width':im.width,'height':im.height,'sha256':hashlib.sha256(target.read_bytes()).hexdigest(),'captureRun':run,'timestamp':item['timestamp']})
    cards.append(f'<article data-language="{locale}" data-search="{html.escape(title.lower())}"><button class="shot" aria-label="Enlarge {html.escape(title)}" onclick="show(this)"><img loading="lazy" alt="{html.escape(title)} — {locale}" src="data:image/webp;base64,{encoded}"></button><p class="code">{html.escape(name)}</p><h3>{html.escape(title)}</h3><a href="images/{name}.png" download>Original PNG ↗</a></article>')
(out/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
counts={l:sum(m['language']==l for m in manifest) for l in ['en','ar','tr','accessibility']}
header='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Arca · UX handoff</title><style>
:root{--ink:#17281f;--green:#1f5d3f;--paper:#f9f5e9;--card:#fffdf5}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.6 system-ui,sans-serif}header,main{max-width:1360px;margin:auto;padding:32px}header{padding-top:60px}h1{font-size:clamp(36px,5vw,64px);line-height:1.05;letter-spacing:-2px;max-width:800px;margin:16px 0 24px}h2{font-size:27px;line-height:1.2}h3{font-size:17px;line-height:1.35;margin:8px 0}p{max-width:850px}.eyebrow,.code{font-size:12px;letter-spacing:.07em;text-transform:uppercase}.eyebrow{color:var(--green);font-weight:700}.facts,.flow{display:flex;flex-wrap:wrap;gap:12px}.facts span,.node{background:var(--card);border:1px solid #d7dfd4;border-radius:12px;padding:12px 16px}.flow{align-items:center}.node b{display:block}.flow small{display:block}.flowbox{background:#edf0e7;border-radius:18px;padding:24px;margin:20px 0}.notes{border-left:4px solid #b96e21;padding:16px 24px;background:var(--card)}.notes li{margin:8px 0}.controls{position:sticky;top:0;z-index:2;background:#f9f5e9f2;backdrop-filter:blur(10px);border-bottom:1px solid #cdd7c8;padding:14px 0;display:flex;gap:8px;flex-wrap:wrap}button,input{font:inherit;border:1px solid #b6c6b8;border-radius:10px;padding:10px 14px;min-height:44px;background:var(--card);color:var(--ink)}button{cursor:pointer}button[aria-pressed=true]{background:var(--green);color:white}.controls input{margin-left:auto;min-width:220px}.gallery{display:grid;grid-template-columns:repeat(auto-fill,minmax(225px,1fr));gap:24px;margin-top:30px}article{padding:12px;background:var(--card);border:1px solid #d9dfd5;border-radius:16px}article[hidden]{display:none}.shot{border:0;padding:0;background:none;display:block;width:100%;min-height:0}.shot img{width:100%;height:auto;display:block;border-radius:10px}.code{color:#59715e;margin:12px 0 0;overflow-wrap:anywhere}a{color:var(--green)}dialog{border:0;border-radius:18px;background:var(--paper);max-height:96vh;padding:12px;max-width:96vw}dialog::backdrop{background:#081b13cf}dialog img{display:block;max-height:80vh;max-width:90vw;width:auto}dialog form{display:flex;justify-content:space-between;align-items:center;gap:12px}footer{padding:32px;color:#59715e}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid #b96e21;outline-offset:3px}@media(max-width:600px){header,main{padding:20px}.controls input{margin:0;width:100%}.gallery{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}article{padding:7px}h3{font-size:14px}.code{font-size:10px}}
</style><header><div class="eyebrow">Arca / Product & design / 5 November 2026</div><h1>Everyday records.<br>Every main journey.</h1><p>Native app screenshots for your UX/UI designer: English, Arabic right-to-left, Turkish, and accessibility text sizes. The forest green, warm paper and archive identity remain the brand baseline.</p>'''
header+=f'<div class="facts"><span><b>{len(manifest)}</b> distinct screenshots</span><span>EN {counts["en"]} · AR {counts["ar"]} · TR {counts["tr"]}</span><span>{counts["accessibility"]} enlarged-text views</span><span>iPhone 17e · 390 × 844 pt</span></div></header><main>'
header+='''<h2>Journey map</h2><div class="flowbox"><div class="flow"><div class="node"><b>Welcome</b><small>Language → storage choice</small></div><span>→</span><div class="node"><b>Account or local-only</b><small>Consent · sign in · recovery</small></div><span>→</span><div class="node"><b>Starter collections</b><small>Backend suggestions · optional</small></div><span>→</span><div class="node"><b>Home</b><small>Spaces · search · favorites</small></div></div></div><div class="flowbox"><div class="flow"><div class="node"><b>Create with AI</b><small>Describe → prepared prompt</small></div><span>→</span><div class="node"><b>External assistant</b><small>Copy / open ChatGPT, Claude, Gemini</small></div><span>→</span><div class="node"><b>Import reply</b><small>Strict JSON validation → preview</small></div><span>→</span><div class="node"><b>Collection</b><small>New record → detail → edit</small></div></div><p>Alternative entry paths: suggested collection → copy; manual builder → define fields. Existing collections support field editing and explicit sensitive-data consent.</p></div><div class="flowbox"><div class="flow"><div class="node"><b>Insights</b><small>Totals · categories · expirations</small></div><div class="node"><b>Settings</b><small>Language · appearance · app lock</small></div><div class="node"><b>Storage & sync</b><small>Mode change · conflicts · devices</small></div><div class="node"><b>Recovery & account</b><small>Backups · encryption · delete account</small></div><div class="node"><b>Pro</b><small>Account prerequisite · billing boundary</small></div></div></div>
<div class="notes"><strong>Read before designing</strong><ul><li>These are real production SwiftUI views mounted in a separate test app. All records, accounts and recovery phrases are fictional fixtures. Connected-account screenshots use a disposable local backend.</li><li>This captures the source changes after TestFlight build 5. It does not claim that build 5 already includes these fixes.</li><li>Keep the three creation paths clear. AI is the suggested first path; users can also choose a suggestion or use the manual builder.</li><li>Distinguish local-only from synced data, and explain sensitive-data consent before upload. Never translate a user's existing records when the interface language changes.</li><li>Prices, completed purchases, RevenueCat-authored paywall variants, third-party assistant websites, iOS file-provider sheets, biometric system prompts, and every possible network/conflict/error combination are outside this screenshot set. The Pro capture is the actual account-required state, not a mocked purchase screen.</li><li>Large-text views show reflow at the largest accessibility size. Native label audits passed on the tested welcome, account and manual-builder views; device VoiceOver, Switch Control, complete contrast auditing and native-speaker copy review remain release QA.</li></ul></div>
<h2>Screen library</h2><p>Filter by language or search a journey. Click a screenshot to enlarge it. Original PNG files are included alongside this HTML in the ZIP. The embedded previews work without a network connection.</p><div class="controls" role="group" aria-label="Filter screenshots"><button data-filter="en" aria-pressed="true" onclick="filter(this)">English</button><button data-filter="ar" aria-pressed="false" onclick="filter(this)">العربية</button><button data-filter="tr" aria-pressed="false" onclick="filter(this)">Türkçe</button><button data-filter="accessibility" aria-pressed="false" onclick="filter(this)">Large text</button><button data-filter="all" aria-pressed="false" onclick="filter(this)">All</button><input id="search" type="search" placeholder="Search screens…" aria-label="Search screenshots" oninput="refresh()"></div><p id="count" aria-live="polite"></p><section class="gallery">'''
footer='''</section><dialog id="viewer"><form method="dialog"><strong id="caption"></strong><button aria-label="Close enlarged screenshot">Close ×</button></form><img id="large" alt=""></dialog></main><footer>Arca · Native SwiftUI · Local-first records · hi@kawkbi.com</footer><script>let language='en';const cards=[...document.querySelectorAll('article')];function refresh(){const q=document.querySelector('#search').value.toLowerCase();let n=0;for(const c of cards){const visible=(language==='all'||c.dataset.language===language)&&c.dataset.search.includes(q);c.hidden=!visible;if(visible)n++;}document.querySelector('#count').textContent=n+' screenshots shown';}function filter(b){language=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));refresh();}function show(b){const img=b.querySelector('img');document.querySelector('#large').src=img.src;document.querySelector('#large').alt=img.alt;document.querySelector('#caption').textContent=img.alt;document.querySelector('#viewer').showModal();}refresh();</script></html>'''
(out/'index.html').write_text(header+'\n'.join(cards)+footer)
(out/'README.txt').write_text('Open index.html in a browser. Filter EN / AR / TR / Large text.\nImages contains the original, unmodified native PNG captures.\nThe HTML previews are embedded and work offline. Keep the images folder for PNG downloads.\nAll data and recovery phrases are fictional fixtures. See the coverage notes in the HTML.\n')
print(json.dumps({'screenshots':len(manifest),'counts':counts,'html_bytes':(out/'index.html').stat().st_size}))
